long long __divdi3(long long numerator, long long denominator)
{
    uint64_t dividend;
    uint64_t divisor;
    uint64_t quotient;
    int negate = 0;

    if (denominator == 0)
        return 0;

    if (numerator < 0) {
        dividend = (uint64_t)(-numerator);
        negate = !negate;
    } else {
        dividend = (uint64_t)numerator;
    }

    if (denominator < 0) {
        divisor = (uint64_t)(-denominator);
        negate = !negate;
    } else {
        divisor = (uint64_t)denominator;
    }

    quotient = div64_u64(dividend, divisor);
    return negate ? -(long long)quotient : (long long)quotient;
}

