    printk(KERN_NOTICE "tx_isp_t40_recovered: exit freed %u lifted vmalloc areas (replaced %u, overflow %u)\n",
           n, t40_vtrack_replaced, t40_vtrack_overflow);
    t40_vtrack_live = 0;
