static void regtrace_note_send_event(uint32_t event)
{
    switch (event) {
    case 0x03000001U:
        regtrace_send_event_diag.get_fmt++;
        break;
    case REGTRACE_TX_ISP_EVENT_FRAME_SET_FMT:
        regtrace_send_event_diag.set_fmt++;
        break;
    case REGTRACE_TX_ISP_EVENT_FRAME_STREAMON:
        regtrace_send_event_diag.streamon++;
        break;
    case REGTRACE_TX_ISP_EVENT_FRAME_STREAMOFF:
        regtrace_send_event_diag.streamoff++;
        break;
    case REGTRACE_TX_ISP_EVENT_FRAME_QBUF:
        regtrace_send_event_diag.qbuf++;
        break;
    case REGTRACE_TX_ISP_EVENT_FRAME_DONE:
        regtrace_send_event_diag.done++;
        break;
    case REGTRACE_TX_ISP_EVENT_FRAME_CLEAR:
        regtrace_send_event_diag.clear++;
        break;
    case REGTRACE_TX_ISP_EVENT_FRAME_SET_BANKS:
        regtrace_send_event_diag.set_banks++;
        break;
    default:
        regtrace_send_event_diag.other++;
        break;
    }
}

