static void regtrace_unregister_bootstrap_devices(void)
{
    int i;

    if (regtrace_debug_proc) {
        proc_remove(regtrace_debug_proc);
        regtrace_debug_proc = NULL;
    }

    for (i = 3; i >= 0; i--) {
        if (regtrace_framechan_misc_registered[i]) {
            misc_deregister(&regtrace_framechan_miscdevs[i]);
            regtrace_framechan_misc_registered[i] = 0;
        }
    }
    if (regtrace_tisp_misc_registered) {
        misc_deregister(&regtrace_tisp_miscdev);
        regtrace_tisp_misc_registered = 0;
    }
    if (regtrace_isp_m0_misc_registered) {
        misc_deregister(&regtrace_isp_m0_miscdev);
        regtrace_isp_m0_misc_registered = 0;
    }
    if (regtrace_tx_isp_misc_registered) {
        misc_deregister(&regtrace_tx_isp_miscdev);
        regtrace_tx_isp_misc_registered = 0;
    }
}

static int regtrace_register_one_misc(struct miscdevice *misc, int *registered)
{
    int ret;

    if (*registered) {
        return 0;
    }

    ret = misc_register(misc);
    if (ret == -EBUSY || ret == -EEXIST) {
        printk(KERN_INFO "tx_isp_t40_recovered: /dev/%s already exists, leaving it in place\n", misc->name);
        return 0;
    }
    if (ret) {
        printk(KERN_ERR "tx_isp_t40_recovered: failed to create /dev/%s: %d\n", misc->name, ret);
        return ret;
    }

    *registered = 1;
    printk(KERN_INFO "tx_isp_t40_recovered: created /dev/%s\n", misc->name);
    return 0;
}

static int regtrace_register_bootstrap_devices(void)
{
    int i;
    int ret;

    ret = regtrace_register_one_misc(&regtrace_tx_isp_miscdev, &regtrace_tx_isp_misc_registered);
    if (ret) {
        return ret;
    }
    ret = regtrace_register_one_misc(&regtrace_isp_m0_miscdev, &regtrace_isp_m0_misc_registered);
    if (ret) {
        goto err_unregister;
    }
    ret = regtrace_register_one_misc(&regtrace_tisp_miscdev, &regtrace_tisp_misc_registered);
    if (ret) {
        goto err_unregister;
    }

    for (i = 0; i < 4; i++) {
        ret = regtrace_register_one_misc(&regtrace_framechan_miscdevs[i], &regtrace_framechan_misc_registered[i]);
        if (ret) {
            goto err_unregister;
        }
    }

#ifdef TX_ISP_T40_DEBUG_PROC
    if (!regtrace_debug_proc) {
        regtrace_debug_proc = proc_create("tx_isp_t40_recovered", 0644, NULL,
                                          &regtrace_debug_proc_fops);
        if (regtrace_debug_proc) {
            printk(KERN_INFO "tx_isp_t40_recovered: created /proc/tx_isp_t40_recovered\n");
        } else {
            printk(KERN_WARNING "tx_isp_t40_recovered: failed to create /proc/tx_isp_t40_recovered\n");
        }
    }
#endif /* TX_ISP_T40_DEBUG_PROC */

    return 0;

err_unregister:
    regtrace_unregister_bootstrap_devices();
    return ret;
}
#endif

/*
 * Unresolved jalr targets: the recovery resolved these indirect calls to the
 * first symbol (private_i2c_set_clientdata), which then wrote its second
 * argument into memory at its first argument. Call a counting no-op instead.
 */
/* #140: call counters (readable in /sys/module/tx_isp_t40/parameters) to prove whether the baseline entries
 * (ispcore_core_ops_init -> 28 sec-init entries, tisp_main_long_tgain_update -> 10 AE event callbacks) are
 * ever entered in the default flow. */
static uint32_t t40_cnt_core_ops_init, t40_cnt_sec_init, t40_cnt_main_long_tgain_update;
module_param_named(cnt_core_ops_init, t40_cnt_core_ops_init, uint, 0444);
module_param_named(cnt_sec_init, t40_cnt_sec_init, uint, 0444);
module_param_named(cnt_main_long_tgain_update, t40_cnt_main_long_tgain_update, uint, 0444);
static uint32_t regtrace_unresolved_jalr_count;
module_param_named(unresolved_jalr_count, regtrace_unresolved_jalr_count, uint, 0444);
static uintptr_t regtrace_unresolved_jalr(uintptr_t a0, uintptr_t a1, uintptr_t a2, uintptr_t a3)
{
    if (regtrace_unresolved_jalr_count++ < 4)
        printk(KERN_WARNING "tx_isp_t40_recovered: unresolved jalr from %pS a0=0x%lx\n",
               __builtin_return_address(0), (unsigned long)a0);
    return 0;
}

