/*
 * Frame-sampled 3A worker. y/uv are physical NV12 plane addresses of the
 * completed frame. Runs in the frame-done workqueue (process context); maps
 * a static 32MB rmem window on first use. Dimensions come from the active
 * frame-channel/sensor format rather than a board-specific override.
 */
/* Conservative proportional trim: 8 gain units per chroma code, bounded. */
static uint32_t regtrace_frame_awb_trim(uint32_t gain, uint32_t mean,
                                        uint32_t target, uint32_t hyst)
{
    uint32_t error, step, limit;
    gain = clamp_t(uint32_t, gain, 0x200U, 0x1800U);
    error = mean > target ? mean - target : target - mean;
    if (error <= hyst)
        return gain;
    limit = max_t(uint32_t, gain / 8U, 1U);
    step = min_t(uint32_t, error * 8U, limit);
    if (mean > target)
        return gain > 0x200U + step ? gain - step : 0x200U;
    return min_t(uint32_t, gain + step, 0x1800U);
}

/* T40-AE-MAXIT-SENSOR: integration ceiling = sensor attribute
 * max_integration_time when known (mirrored into ae_soft_max_it so the
 * readbacks show it), else the ae_soft_max_it parameter. */
static uint32_t regtrace_t40_ae_max_it(void)
{
    uint32_t it = READ_ONCE(regtrace_ae_soft_max_it);

    if (regtrace_ae_soft_max_it_from_sensor &&
        regtrace_is_kernel_ptr(regtrace_sensor_subdev)) {
        uintptr_t attr = regtrace_get_u32((uintptr_t)regtrace_sensor_subdev, 0x304);
        uint32_t s = regtrace_is_kernel_ptr((void *)attr) ?
                     regtrace_get_u16(attr, 0xb8) : 0;

        if (s > regtrace_ae_soft_min_it && s < 0xffffU) {
            it = s;
            if (READ_ONCE(regtrace_ae_soft_max_it) != s)
                WRITE_ONCE(regtrace_ae_soft_max_it, s);
        }
    }
    if (regtrace_ae_user_max_it > regtrace_ae_soft_min_it &&
        regtrace_ae_user_max_it < it)
        it = regtrace_ae_user_max_it;
    return it;
}

