    control[1] = base + (sensor ? 0x90U : 0x80U);
    control[2] = base + (sensor ? 0x70U : 0x60U);
    data[0] = base + (sensor ? 0x54U : 0x44U);
    data[1] = base + (sensor ? 0x94U : 0x84U);
