    n[2] = (uint16_t)(grid_x * 2);
    n[3] = (uint16_t)(grid_x * 3);
    n[4] = (uint16_t)(grid_x * 4);
    n[5] = (uint16_t)(grid_x * 5);
    n[6] = (uint16_t)width;

